class Solution:
    def generateTag(self, caption: str) -> str:
        words = [w for w in caption.split(' ') if w]
        tag = '#'
        for i, w in enumerate(words):
            tag += w.lower() if i == 0 else w[0].upper() + w[1:].lower()
        return ''.join(c for c in tag if c == '#' or c.isalpha())[:100]

