class Solution {
public:
    string generateTag(string caption) {
        string tag = "#";
        stringstream ss(caption);
        string w;
        bool first = true;
        while (ss >> w) {
            for (char &c : w) c = tolower(c);
            if (!first) w[0] = toupper(w[0]);
            first = false;
            tag += w;
        }
        string res;
        for (char c : tag) if (c == '#' || isalpha(c)) res += c;
        return res.substr(0, 100);
    }
};

