class Solution {
    public String generateTag(String caption) {
        StringBuilder tag = new StringBuilder("#");
        boolean first = true;
        for (String w : caption.split(" ")) {
            if (w.isEmpty()) continue;
            String t = w.toLowerCase();
            if (!first) t = Character.toUpperCase(t.charAt(0)) + t.substring(1);
            first = false;
            tag.append(t);
        }
        StringBuilder res = new StringBuilder();
        for (char c : tag.toString().toCharArray())
            if (c == '#' || Character.isLetter(c)) res.append(c);
        return res.length() > 100 ? res.substring(0, 100) : res.toString();
    }
}

