    const words = caption.split(' ').filter(w => w.length);
    let tag = '#';
    words.forEach((w, i) => {
        w = w.toLowerCase();
        if (i > 0) w = w[0].toUpperCase() + w.slice(1);
        tag += w;
    });
    return tag.replace(/[^a-zA-Z#]/g, '').slice(0, 100);
};

