public:
    string generateTag(string caption) {
        string tag = "#";
        stringstream ss(caption); string w; bool first = true;
        while (ss >> w) {
            for (char &c : w) c = tolower(c);
            if (!first) w[0] = toupper(w[0]);
            first = false; tag += w;
        }
        string res;
        regex keep("[A-Za-z#]");
        for (char c : tag) if (regex_match(string(1, c), keep)) res += c;
        return res.substr(0, 100);
    }
};

